/* index.js */
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");
const canvasWrapper = document.getElementById("canvas-wrapper");

// State
let baseImage = null;
let tool = "rect"; // rect, line, arrow, blur
let isDrawing = false;
let startX = 0,
  startY = 0,
  endX = 0,
  endY = 0;

// Zoom (見かけのサイズのみ。canvas.width/height は画像本来の解像度のまま)
const MIN_ZOOM = 0.1;
const MAX_ZOOM = 8;
const ZOOM_STEP = 0.1;
let zoom = 1;

// Annotation Dragging State
let isDraggingAnnot = false;
let draggingAnnotIndex = -1;
let tempShapes = [];

// History
let history = [[]];
let historyIndex = 0;
const MAX_HISTORY = 10;

// UI Elements
const elements = {
  fgColor: document.getElementById("color-fg"),
  bgColor: document.getElementById("color-bg"),
  annotRect: document.getElementById("annot-rect"),
  annotLine: document.getElementById("annot-line"),
  annotArrow: document.getElementById("annot-arrow"),
  annotBlur: document.getElementById("annot-blur"),
  fontFamily: document.getElementById("font-family"),
  annotSize: document.getElementById("annot-size"),
  btnUndo: document.getElementById("btn-undo"),
  btnRedo: document.getElementById("btn-redo"),
  btnZoomIn: document.getElementById("btn-zoom-in"),
  btnZoomOut: document.getElementById("btn-zoom-out"),
  btnZoomReset: document.getElementById("btn-zoom-reset"),
  zoomIndicator: document.getElementById("zoom-indicator"),
};

const circledNumbers = ["①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩", "⑪", "⑫", "⑬", "⑭", "⑮", "⑯", "⑰", "⑱", "⑲", "⑳"];

function getCircledNumber(index) {
  if (index < 20) return circledNumbers[index];
  return `(${index + 1})`;
}

// --- Image Loading ---
function loadImage(src) {
  const img = new Image();
  img.onload = () => {
    canvas.width = img.width;
    canvas.height = img.height;
    baseImage = img;
    history = [[]];
    historyIndex = 0;
    updateButtons();
    applyZoom(zoom);
    render();
  };
  img.src = src;
}

// --- History Management ---
function saveState(shapes) {
  const shapesCopy = JSON.parse(JSON.stringify(shapes));
  history = history.slice(0, historyIndex + 1);
  history.push(shapesCopy);
  if (history.length > MAX_HISTORY + 1) {
    history.shift();
  } else {
    historyIndex++;
  }
  updateButtons();
}

function undo() {
  if (historyIndex > 0) {
    historyIndex--;
    render();
    updateButtons();
  }
}

function redo() {
  if (historyIndex < history.length - 1) {
    historyIndex++;
    render();
    updateButtons();
  }
}

function updateButtons() {
  elements.btnUndo.disabled = historyIndex === 0;
  elements.btnRedo.disabled = historyIndex === history.length - 1;
}

// --- 拡大縮小（表示のみ） ---
function applyZoom(newZoom) {
  zoom = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, newZoom));

  // CSS transform による拡大縮小。canvas.width/height は変更しないため、
  // 保存・コピーされる画像は本来の解像度のままになる。
  canvas.style.transform = zoom === 1 ? "" : `scale(${zoom})`;

  // スケール後の表示寸法に wrapper を合わせて、スクロール領域を正しく確保する
  if (canvas.width && canvas.height) {
    canvasWrapper.style.width = `${canvas.width * zoom}px`;
    canvasWrapper.style.height = `${canvas.height * zoom}px`;
  }

  if (elements.zoomIndicator) {
    elements.zoomIndicator.textContent = `${Math.round(zoom * 100)}%`;
  }
  if (elements.btnZoomIn) elements.btnZoomIn.disabled = zoom >= MAX_ZOOM;
  if (elements.btnZoomOut) elements.btnZoomOut.disabled = zoom <= MIN_ZOOM;
}

function zoomIn() {
  applyZoom(Math.round((zoom + ZOOM_STEP) * 100) / 100);
}

function zoomOut() {
  applyZoom(Math.round((zoom - ZOOM_STEP) * 100) / 100);
}

function zoomReset() {
  applyZoom(1);
}

// マウス位置をキャンバスの本来の座標系（0,0〜canvas.width,canvas.height）に変換する。
// getBoundingClientRect は transform 後の矩形を返すため、比率からスケールを求める。
function getCanvasPointRaw(e) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = rect.width / canvas.width;
  const scaleY = rect.height / canvas.height;
  const px = scaleX === 0 ? 0 : (e.clientX - rect.left) / scaleX;
  const py = scaleY === 0 ? 0 : (e.clientY - rect.top) / scaleY;
  return { x: px, y: py };
}

function getCanvasPoint(e) {
  return clampPointToCanvas(getCanvasPointRaw(e));
}

function isInsideCanvas(p) {
  return p.x >= 0 && p.x <= canvas.width && p.y >= 0 && p.y <= canvas.height;
}

// マウス位置の XY をキャンバス内の座標範囲に制限する。
// キャンバス外にある場合、この制限された点を「仮想のマウス位置」として扱う。
function clampPointToCanvas(p) {
  return {
    x: Math.max(0, Math.min(canvas.width, p.x)),
    y: Math.max(0, Math.min(canvas.height, p.y)),
  };
}

// --- Annotation Positioning ---
function getInitialAnnotPos(shape) {
  const size = parseInt(shape.annotSize);
  let minX = Math.min(shape.startX, shape.endX);
  let minY = Math.min(shape.startY, shape.endY);
  let maxX = Math.max(shape.startX, shape.endX);
  let maxY = Math.max(shape.startY, shape.endY);

  const offset = size + 5;
  const candidates = [
    { x: minX - offset, y: minY - offset },
    { x: maxX + offset, y: minY - offset },
    { x: minX - offset, y: maxY + offset },
    { x: maxX + offset, y: maxY + offset },
    { x: minX + (maxX - minX) / 2, y: minY - offset },
  ];

  for (let c of candidates) {
    if (c.x - size >= 0 && c.y - size >= 0 && c.x + size <= canvas.width && c.y + size <= canvas.height) {
      return { x: c.x, y: c.y };
    }
  }
  return { x: minX, y: minY };
}

// --- Drawing Engine ---
function render(customShapes = null) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (baseImage) {
    ctx.drawImage(baseImage, 0, 0);
  }

  const shapes = customShapes || history[historyIndex];
  let annotCount = 0;

  // 1. まずすべての図形（ぼかし以外）を描画
  shapes.forEach((shape) => {
    if (shape.type !== "blur") {
      drawShape(shape);
    }
  });

  // 2. ぼかしを適用（ベース画像に対して直接作用）
  shapes.forEach((shape) => {
    if (shape.type === "blur") {
      applyBlur(shape);
    }
  });

  // 3. 再度非ぼかし図形を描画（ぼかしの上に線を乗せるため）
  shapes.forEach((shape) => {
    if (shape.type !== "blur") {
      drawShape(shape);
    }
  });

  // 4. 傍記を描画
  shapes.forEach((shape) => {
    if (shape.needsAnnot) {
      drawAnnotation(shape, annotCount);
      annotCount++;
    }
  });

  // プレビュー表示
  if (isDrawing) {
    const previewShape = {
      type: tool,
      startX,
      startY,
      endX,
      endY,
      color: elements.fgColor.value,
    };
    if (tool === "blur") {
      drawBlurPreview(previewShape);
    } else {
      drawShape(previewShape);
    }
  }
}

function drawShape(shape) {
  ctx.strokeStyle = shape.color;
  ctx.lineWidth = 3;
  ctx.lineJoin = "round";
  ctx.lineCap = "round";

  ctx.beginPath();
  if (shape.type === "rect") {
    ctx.rect(shape.startX, shape.startY, shape.endX - shape.startX, shape.endY - shape.startY);
    ctx.stroke();
  } else if (shape.type === "line" || shape.type === "arrow") {
    ctx.moveTo(shape.startX, shape.startY);
    ctx.lineTo(shape.endX, shape.endY);
    ctx.stroke();

    if (shape.type === "arrow") {
      const angle = Math.atan2(shape.endY - shape.startY, shape.endX - shape.startX);
      const headlen = 15;
      ctx.beginPath();
      ctx.moveTo(shape.endX, shape.endY);
      ctx.lineTo(shape.endX - headlen * Math.cos(angle - Math.PI / 6), shape.endY - headlen * Math.sin(angle - Math.PI / 6));
      ctx.moveTo(shape.endX, shape.endY);
      ctx.lineTo(shape.endX - headlen * Math.cos(angle + Math.PI / 6), shape.endY - headlen * Math.sin(angle + Math.PI / 6));
      ctx.stroke();
    }
  }
}

// キャンバスの総画素数に応じたぼかし半径: ceil(総画素数 / 250000)
// 拡大縮小は見かけのサイズのみなので、実画像の解像度（canvas.width × canvas.height）を基準にする
function getBlurRadius() {
  const totalPixels = canvas.width * canvas.height;
  return Math.max(10, Math.ceil(totalPixels / 250000));
}

// ぼかしの適用
function applyBlur(shape) {
  const x = Math.min(shape.startX, shape.endX);
  const y = Math.min(shape.startY, shape.endY);
  const w = Math.abs(shape.endX - shape.startX);
  const h = Math.abs(shape.endY - shape.startY);

  if (w < 1 || h < 1) return;

  ctx.save();
  ctx.beginPath();
  ctx.rect(x, y, w, h);
  ctx.clip();

  // キャンバスサイズに応じたぼかしを適用
  ctx.filter = `blur(${getBlurRadius()}px)`;
  if (baseImage) {
    ctx.drawImage(baseImage, 0, 0);
  }
  ctx.filter = "none";
  ctx.restore();
}

// ぼかしのプレビュー表示
function drawBlurPreview(shape) {
  const x = Math.min(shape.startX, shape.endX);
  const y = Math.min(shape.startY, shape.endY);
  const w = Math.abs(shape.endX - shape.startX);
  const h = Math.abs(shape.endY - shape.startY);

  ctx.save();
  ctx.fillStyle = "rgba(0, 0, 0, 0.25)";
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = "#ffffff";
  ctx.lineWidth = 1;
  ctx.strokeRect(x, y, w, h);
  ctx.restore();
}

function drawAnnotation(shape, count) {
  if (shape.annotX === undefined || shape.annotY === undefined) return;

  const text = getCircledNumber(count);
  const size = parseInt(shape.annotSize);

  ctx.beginPath();
  ctx.arc(shape.annotX, shape.annotY, size, 0, Math.PI * 2);
  ctx.fillStyle = shape.bgColor;
  ctx.fill();

  ctx.font = `bold ${size * 1.5}px ${shape.font}`;
  ctx.fillStyle = shape.color;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, shape.annotX, shape.annotY);
}

// --- Mouse Events ---
// ドラッグ中は window 上でイベントを追跡するため、
// カーソルがキャンバスからはみ出してもマウス位置を追い続けられる。
function addDragTracking() {
  window.addEventListener("mousemove", onDragMove);
  window.addEventListener("mouseup", onDragEnd);
}

function removeDragTracking() {
  window.removeEventListener("mousemove", onDragMove);
  window.removeEventListener("mouseup", onDragEnd);
}

function applyShiftConstraint(curX, curY, shiftKey) {
  if (shiftKey) {
    if (tool === "line" || tool === "arrow") {
      const dx = Math.abs(curX - startX);
      const dy = Math.abs(curY - startY);
      if (dx > dy) curY = startY;
      else curX = startX;
    } else if (tool === "blur" || tool === "rect") {
      // 正方形に制限
      const size = Math.max(Math.abs(curX - startX), Math.abs(curY - startY));
      curX = startX + (curX > startX ? size : -size);
      curY = startY + (curY > startY ? size : -size);
    }
  }
  return { x: curX, y: curY };
}

function onDragMove(e) {
  const raw = getCanvasPointRaw(e);

  if (isDraggingAnnot) {
    const virtual = clampPointToCanvas(raw);
    tempShapes[draggingAnnotIndex].annotX = virtual.x;
    tempShapes[draggingAnnotIndex].annotY = virtual.y;
    render(tempShapes);
    return;
  }

  if (isDrawing) {
    const constrained = applyShiftConstraint(raw.x, raw.y, e.shiftKey);
    // マウス位置をキャンバス内に制限した点を仮想のマウス位置としてプレビューする
    const virtual = clampPointToCanvas(constrained);
    endX = virtual.x;
    endY = virtual.y;
    render();
  }
}

function onDragEnd(e) {
  if (isDraggingAnnot) {
    isDraggingAnnot = false;
    draggingAnnotIndex = -1;
    saveState(tempShapes);
    render();
    removeDragTracking();
    return;
  }

  if (!isDrawing) {
    removeDragTracking();
    return;
  }
  isDrawing = false;
  removeDragTracking();

  const raw = getCanvasPointRaw(e);
  const constrained = applyShiftConstraint(raw.x, raw.y, e.shiftKey);

  // 始点がキャンバス外なら描写しない（始点は canvas 上の mousedown から取得するため通常は内側）。
  if (!isInsideCanvas({ x: startX, y: startY })) {
    render();
    return;
  }

  // マウス位置の XY をキャンバス内の XY までに制限した値を仮想のマウス位置として描写する。
  // ドラッグ中のプレビューと同じ制限方法を使い、プレビューと確定結果を一致させる。
  const virtual = clampPointToCanvas(constrained);
  endX = virtual.x;
  endY = virtual.y;

  if (Math.abs(endX - startX) < 5 && Math.abs(endY - startY) < 5) {
    render();
    return;
  }

  // 傍記が必要かどうか判定
  let needsAnnot = false;
  if (tool === "rect" && elements.annotRect.checked) needsAnnot = true;
  if (tool === "line" && elements.annotLine.checked) needsAnnot = true;
  if (tool === "arrow" && elements.annotArrow.checked) needsAnnot = true;
  if (tool === "blur" && elements.annotBlur.checked) needsAnnot = true;

  const newShape = {
    type: tool,
    startX,
    startY,
    endX,
    endY,
    color: elements.fgColor.value,
    bgColor: elements.bgColor.value,
    needsAnnot: needsAnnot,
    annotSize: elements.annotSize.value,
    font: elements.fontFamily.value,
  };

  if (needsAnnot) {
    const pos = getInitialAnnotPos(newShape);
    newShape.annotX = pos.x;
    newShape.annotY = pos.y;
  }

  const currentShapes = [...history[historyIndex]];
  currentShapes.push(newShape);
  saveState(currentShapes);
  render();
}

canvas.addEventListener("mousedown", (e) => {
  if (e.button !== 0) return;
  const point = getCanvasPoint(e);
  const mouseX = point.x;
  const mouseY = point.y;

  const currentShapes = history[historyIndex];

  // 傍記のドラッグ判定
  for (let i = currentShapes.length - 1; i >= 0; i--) {
    const shape = currentShapes[i];
    if (shape.needsAnnot && shape.annotX !== undefined && shape.annotY !== undefined) {
      const dist = Math.hypot(mouseX - shape.annotX, mouseY - shape.annotY);
      if (dist <= parseInt(shape.annotSize)) {
        isDraggingAnnot = true;
        draggingAnnotIndex = i;
        tempShapes = JSON.parse(JSON.stringify(currentShapes));
        addDragTracking();
        return;
      }
    }
  }

  // 描画開始
  startX = mouseX;
  startY = mouseY;
  endX = startX;
  endY = startY;
  isDrawing = true;
  addDragTracking();
});

// Ctrl + マウスホイールで拡大縮小（ブラウザ標準のズームも抑制する）
const zoomTarget = document.getElementById("canvas-container") || canvas;
zoomTarget.addEventListener(
  "wheel",
  (e) => {
    if (!e.ctrlKey && !e.metaKey) return;
    e.preventDefault();
    if (e.deltaY < 0) zoomIn();
    else if (e.deltaY > 0) zoomOut();
  },
  { passive: false },
);

elements.btnZoomIn.addEventListener("click", zoomIn);
elements.btnZoomOut.addEventListener("click", zoomOut);
elements.btnZoomReset.addEventListener("click", zoomReset);

// --- Keyboard ---
window.addEventListener("keydown", (e) => {
  if (!e.ctrlKey && !e.altKey && !e.metaKey) {
    if (e.key === "1") setTool("rect");
    if (e.key === "2") setTool("line");
    if (e.key === "3") setTool("arrow");
    if (e.key === "4") setTool("blur");
  }

  if (e.ctrlKey || e.metaKey) {
    if (e.key === "s") {
      e.preventDefault();
      saveImage();
    }
    if (e.key === "c") {
      e.preventDefault();
      copyImage();
    }
    if (e.key === "z") {
      e.preventDefault();
      undo();
    }
    if (e.key === "y") {
      e.preventDefault();
      redo();
    }
    if (e.key === "+" || e.key === "=") {
      e.preventDefault();
      zoomIn();
    }
    if (e.key === "-") {
      e.preventDefault();
      zoomOut();
    }
    if (e.key === "0") {
      e.preventDefault();
      zoomReset();
    }
  }
});

function setTool(newTool) {
  document.querySelector("#tool-selected").textContent = { rect: "描写: 矩形", line: "描写: 直線", arrow: "描写: 矢印", blur: "描写: ぼかし" }[newTool];
  tool = newTool;
  //document.querySelectorAll('[id^="tool-"]').forEach((el) => (el.className = ""));
  //const idx = { rect: 1, line: 2, arrow: 3, blur: 4 }[newTool];
  //document.getElementById("tool-" + idx).className = "active-tool";
}

// --- 画像入力関連 ---
window.addEventListener("paste", (e) => {
  const items = e.clipboardData.items;
  for (let i = 0; i < items.length; i++) {
    if (items[i].type.indexOf("image") !== -1) {
      loadImage(URL.createObjectURL(items[i].getAsFile()));
      e.preventDefault();
      break;
    }
  }
});

window.addEventListener("dragover", (e) => e.preventDefault());
window.addEventListener("drop", (e) => {
  e.preventDefault();
  if (e.dataTransfer.files.length > 0) {
    const file = e.dataTransfer.files[0];
    if (file.type.startsWith("image/")) {
      loadImage(URL.createObjectURL(file));
    }
  }
});

document.getElementById("btn-open").addEventListener("click", () => {
  document.getElementById("file-input").click();
});
document.getElementById("file-input").addEventListener("change", (e) => {
  if (e.target.files[0]) loadImage(URL.createObjectURL(e.target.files[0]));
});

// --- 保存・コピー ---
function saveImage() {
  const link = document.createElement("a");
  link.download = "edited_image.png";
  link.href = canvas.toDataURL("image/png");
  link.click();
}

async function copyImage() {
  canvas.toBlob(async (blob) => {
    try {
      await navigator.clipboard.write([new ClipboardItem({ "image/png": blob })]);
      alert("クリップボードにコピーしました");
    } catch {
      alert("コピーに失敗しました。");
    }
  });
}

document.getElementById("btn-save").addEventListener("click", saveImage);
document.getElementById("btn-copy").addEventListener("click", copyImage);
elements.btnUndo.addEventListener("click", undo);
elements.btnRedo.addEventListener("click", redo);
document.getElementById("btn-help").addEventListener("click", () => {
  document.getElementById("helpModel").style.display = "block";
});

updateButtons();
applyZoom(zoom);
(function () {
  const ua = navigator.userAgent;
  const isFirefox = /Firefox/.test(ua);
  if (!isFirefox) {
    document.body.outerHTML = '<a href="https://www.firefox.com/download/">Download Firefox</a>';
  }
})();
